        int ans = 0;
        bool neg = false;
        char c;
        while ((c = getchar()) != EOF) {
            if (c == '-') {
                neg = true;
                break;
            } else if (isdigit(c)) {
                ans = c - '0';
                while ((c = getchar()) != EOF && isdigit(c))
                    ans = ans * 10 + (c - '0');
                if (neg) ans = -ans;
                return ans;
            }
        }
        return ans;
    }

    static long long readLong() {
        long long ans = 0;
        bool neg = false;
        char c;
        while ((c = getchar()) != EOF) {
            if (c == '-') {
                neg = true;
                break;
            } else if (isdigit(c)) {
                ans = c - '0';
                while ((c = getchar()) != EOF && isdigit(c))
                    ans = ans * 10 + (c - '0');
                if (neg) ans = -ans;
                return ans;
            }
        }
        return ans;
    }

    static std::string readString() {
        std::string b;
        char c;
        bool start = false;
        while ((c = getchar()) != EOF) {
            if (!isspace(c)) {
